<script setup lang="ts">
import { onMounted, computed } from 'vue';import { useRoute } from 'vue-router';import TopBar from '@/components/ui/TopBar.vue';import Avatar from '@/components/ui/Avatar.vue';import { useInboxStore } from '@/stores/inbox';
const route=useRoute(),inbox=useInboxStore();const id=String(route.params.id);onMounted(()=>inbox.loadOne(id));const r=computed(()=>inbox.current);
async function resolve(decision:'accepted'|'declined'){await inbox.resolve(id,decision)}
</script>
<template><section class="screen"><TopBar back title="Заявка гостя"/><div v-if="r" class="request-detail"><Avatar :name="r.applicant?.display_name||'Гость'" :src="r.applicant?.avatar_url" size="lg"/><small>Хочет попасть на</small><h1>{{r.event?.title}}</h1><h2>{{r.applicant?.display_name}}</h2><p class="lead">{{r.note||'Пользователь не добавил сообщение.'}}</p><div class="inline-stats"><span>★ {{r.applicant?.rating||5}}</span><span>{{r.applicant?.verified?'Telegram подтверждён':''}}</span><span>{{r.status}}</span></div><div v-if="r.status==='pending'" class="action-row"><button class="secondary" @click="resolve('declined')">Отклонить</button><button class="primary" @click="resolve('accepted')">Принять гостя</button></div><RouterLink v-else-if="r.status==='accepted'" :to="`/chat/${r.event_id}`" class="primary link-button">Открыть чат события</RouterLink></div><div v-else class="loading">Загружаем заявку…</div></section></template>
